def compute_kv_cache(past_kv, new_keys, new_values):
    k = torch.cat([past_kv['k'], new_keys], dim=-2) if past_kv else new_keys
    v = torch.cat([past_kv['v'], new_values], dim=-2) if past_kv else new_values
    return {'k': k, 'v': v}

